class Solution {
public:
    long long countPairs(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        vector<int> diff(n);
        for (int i = 0; i < n; ++i) diff[i] = nums1[i] - nums2[i];
        sort(diff.begin(), diff.end());

        long long ans = 0;
        int left = 0, right = n - 1;
        while (left < right) {
            if (diff[left] + diff[right] > 0) {
                ans += right - left;
                right--;
            } else {
                left++;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long countPairs(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[] diff = new int[n];
        for (int i = 0; i < n; ++i) diff[i] = nums1[i] - nums2[i];
        Arrays.sort(diff);

        long ans = 0;
        int left = 0, right = n - 1;
        while (left < right) {
            if (diff[left] + diff[right] > 0) {
                ans += right - left;
                right--;
            } else {
                left++;
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @return {number}
