var countPairs = function(nums1, nums2) {
    const n = nums1.length;
    const diff = new Int32Array(n);
    for (let i = 0; i < n; ++i) diff[i] = nums1[i] - nums2[i];
    diff.sort();

    let ans = 0;
    let left = 0, right = n - 1;
    while (left < right) {
        if (diff[left] + diff[right] > 0) {
            ans += right - left;
            right--;
        } else {
            left++;
        }
    }
    return ans;
};
